        vakalar = [v for v in vakalar if any(x in v[1] for x in istenen)]
    with cf.ThreadPoolExecutor(4) as ex:
        sonuc = list(ex.map(lambda v: vaka(*v), vakalar))
    for r in sonuc:
        print("=" * 72)
        print(f"{r['ad']}  rc={r['rc']}")
