# -*- coding: utf-8 -*-
import os, sys, subprocess, tempfile, shutil
sys.stdout.reconfigure(encoding="utf-8")
EXE = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb\bin\uxb_kilavuz_20261007.exe"
BIN = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb\bin"


def calis(k, cwd, sure=240):
    try:
        r = subprocess.run(k, cwd=cwd, capture_output=True, timeout=sure)
        return r.returncode, [s for s in (r.stdout + r.stderr).decode("utf-8", "replace").splitlines() if s.strip() and not s.startswith("INFO")]
    except subprocess.TimeoutExpired:
        return -9, ["ZAMAN_ASIMI"]


def dene(ad, kod, dosyalar):
    d = tempfile.mkdtemp(prefix="imp2_")
    open(os.path.join(d, "p.uxb"), "w", encoding="utf-8").write(kod)
    for yol, icerik in dosyalar.items():
        os.makedirs(os.path.dirname(os.path.join(d, yol)) or d, exist_ok=True)
        open(os.path.join(d, yol), "w", encoding="utf-8").write(icerik)
    print("=" * 60, ad)
    rc, c = calis([EXE, "run", "p.uxb", "--out-root", os.path.join(d, "a")], d)
    print("AST:", rc, c[-3:])
    rc, c = calis([EXE, "bld", "p.uxb", "--build-x64", "--build-x64-out", os.path.join(d, "p.exe"), "--out-root", os.path.join(d, "x")], d)
    print("bld:", rc, c[-3:])
    if os.path.exists(os.path.join(d, "p.exe")):
        for f in os.listdir(BIN):
            if f.lower().endswith(".dll"):
                try:
                    shutil.copy(os.path.join(BIN, f), d)
                except Exception:
                    pass
        rc2, c2 = calis([os.path.join(d, "p.exe")], d)
        print("x64:", rc2, c2[-3:])
    izler = []
    for dp, dn, fn in os.walk(d):
