# -*- coding: utf-8 -*-
"""libsx/*/*.bas ve include/modules/*.uxmh dosyalarından kütüphane işlev envanteri çıkarır."""
import os, re, sys, json
sys.stdout.reconfigure(encoding="utf-8")
KOK = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
LIBSX = os.path.join(KOK, "libsx")
MOD = os.path.join(KOK, "include", "modules")
sonuc = {}
for ad in sorted(os.listdir(MOD)):
    if not ad.endswith(".uxmh"):
        continue
    lib = ad[:-5]
    govde = open(os.path.join(MOD, ad), encoding="utf-8", errors="replace").read()
    hedefler = re.findall(r'INCLUDE\s+"([^"]+)"', govde)
    kayit = {"hedef": hedefler, "ns": [], "islev": [], "dll": set(), "const": 0, "type": 0}
    for h in hedefler:
        p = os.path.join(KOK, h.replace("/", os.sep))
        if not os.path.exists(p):
            kayit["eksik_dosya"] = h
            continue
        for s in open(p, encoding="utf-8", errors="replace").read().splitlines():
            t = s.strip()
            m = re.match(r"(?i)^NAMESPACE\s+(\w+)", t)
            if m:
                kayit["ns"].append(m.group(1))
            m = re.match(r"(?i)^(FUNCTION|SUB)\s+(\w+)\s*\((.*?)\)(?:\s+AS\s+(\w+))?", t)
            if m:
                kayit["islev"].append(f"{m.group(1).upper()} {m.group(2)}({m.group(3)})" + (f" AS {m.group(4)}" if m.group(4) else ""))
            for d in re.findall(r'CALL\(DLL,\s*"([^"]+)"', t):
                kayit["dll"].add(d)
            if re.match(r"(?i)^CONST\b", t):
                kayit["const"] += 1
            if re.match(r"(?i)^TYPE\b", t):
                kayit["type"] += 1
    kayit["dll"] = sorted(kayit["dll"])
    sonuc[lib] = kayit
json.dump(sonuc, open(os.path.join(os.environ["TEMP"], "kv2", "lib_envanter.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
for lib, k in sonuc.items():
    print(f"{lib:<22} ns={','.join(k['ns']) or '-':<22} işlev={len(k['islev']):<4} dll={','.join(k['dll']) or '-':<28} {('EKSİK DOSYA ' + k['eksik_dosya']) if k.get('eksik_dosya') else ''} hedef={k['hedef']}")

