def tri(x, a, b, c):
    if x <= a or x >= c:
        return 0.0
    if x == b:
        return 1.0
    return (x - a) / (b - a) if x < b else (c - x) / (c - b)


def trap(x, a, b, c, d):
    if x <= a or x >= d:
        return 0.0
    if b <= x <= c:
        return 1.0
    return (x - a) / (b - a) if x < b else (d - x) / (d - c)


def fan(t, h):
    soguk = trap(t, -20, -20, 8, 16)
    ilik = tri(t, 12, 22, 32)
    sicak = trap(t, 26, 34, 60, 60)
