    kurallar = [(soguk, 10.0), (ilik, 40.0), (min(sicak, kuru), 70.0), (min(sicak, nemli), 100.0)]
    pay = sum(w * o for w, o in kurallar)
    payda = sum(w for w, o in kurallar)
