        return 1.0
    return (x - a) / (b - a) if x < b else (c - x) / (c - b)


def trap(x, a, b, c, d):
    if x <= a or x >= d:
        return 0.0
    if b <= x <= c:
        return 1.0
    return (x - a) / (b - a) if x < b else (d - x) / (d - c)


def fan(t, h):
    soguk = trap(t, -20, -20, 8, 16)
    ilik = tri(t, 12, 22, 32)
    sicak = trap(t, 26, 34, 60, 60)
    nemli = trap(h, 40, 70, 100, 100)
    kuru = 1.0 - nemli
    kurallar = [(soguk, 10.0), (ilik, 40.0), (min(sicak, kuru), 70.0), (min(sicak, nemli), 100.0)]
    pay = sum(w * o for w, o in kurallar)
    payda = sum(w for w, o in kurallar)
    return pay / payda if payda else 0.0


for t, h in [(5, 50), (22, 50), (30, 30), (36, 90), (28, 55)]:
    print(t, h, round(fan(t, h), 4))

