# -*- coding: utf-8 -*-
"""uxhttp davranış yoklaması: yerel sunucu + MIR/x64 çalıştırma (ham çıktı)."""
import json, os, shutil, subprocess, sys, tempfile, threading, time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
sys.stdout.reconfigure(encoding="utf-8")
KOK = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
EXE = os.path.join(KOK, "bin", "uxb_kilavuz_20261007.exe")
RT = os.path.join(KOK, "bin", "uxb_runtime.dll")


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def yanit(self, kod, govde, tur="text/plain; charset=utf-8", ek=None):
        b = govde.encode("utf-8")
        self.send_response(kod)
        self.send_header("Content-Type", tur)
        self.send_header("Content-Length", str(len(b)))
        for k, v in (ek or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(b)

    def do_GET(self):
        if self.path == "/merhaba":
            self.yanit(200, "merhaba dunya")
        elif self.path == "/yonlendir":
            self.yanit(302, "", ek={"Location": "/merhaba"})
        elif self.path == "/yavas":
            time.sleep(3)
            self.yanit(200, "gec geldim")
        elif self.path == "/hata":
            self.yanit(500, "sunucu hatasi")
        elif self.path == "/baslik":
            self.yanit(200, "anahtar=" + str(self.headers.get("X-Anahtar")) + ";ua=" + str(self.headers.get("User-Agent")))
        elif self.path == "/buyuk":
            self.yanit(200, "x" * 100000)
        elif self.path == "/turkce":
            self.yanit(200, "çğıöşü İĞ")
        else:
            self.yanit(404, "bulunamadi")

    def do_POST(self):
        n = int(self.headers.get("Content-Length", "0"))
        veri = self.rfile.read(n).decode("utf-8")
        if self.path == "/api/topla":
            d = json.loads(veri)
            self.yanit(200, json.dumps({"adet": len(d["sayilar"]), "toplam": sum(d["sayilar"]), "anahtar": self.headers.get("X-Anahtar")}), "application/json")
        else:
            self.yanit(200, "yontem=POST;gelen=" + veri + ";tur=" + str(self.headers.get("Content-Type")))

    def do_PUT(self):
        n = int(self.headers.get("Content-Length", "0"))
        veri = self.rfile.read(n).decode("utf-8")
        self.yanit(200, "yontem=PUT;gelen=" + veri)

    def do_DELETE(self):
        self.yanit(200, "yontem=DELETE")


sunucu = ThreadingHTTPServer(("127.0.0.1", 0), H)
port = sunucu.server_address[1]
threading.Thread(target=sunucu.serve_forever, daemon=True).start()

kaynak = open(sys.argv[1], encoding="utf-8").read().replace("{PORT}", str(port))
d = tempfile.mkdtemp(prefix="http_")
yol = os.path.join(d, "p.uxb")
open(yol, "w", encoding="utf-8").write(kaynak)
motorlar = sys.argv[2].split(",") if len(sys.argv) > 2 else ["MIR"]


def calis(k, cwd, sure=120):
    try:
        r = subprocess.run(k, cwd=cwd, capture_output=True, timeout=sure)
        return r.returncode, [s.rstrip() for s in (r.stdout + r.stderr).decode("utf-8", "replace").splitlines() if s.strip() and not s.startswith(("INFO", "WARN"))]
    except subprocess.TimeoutExpired:
        return -9, ["ZAMAN_ASIMI"]


for m in motorlar:
    if m == "AST":
        rc, c = calis([EXE, "run", yol, "--out-root", os.path.join(d, "a")], d)
    elif m == "MIR":
        rc, c = calis([EXE, "run", yol, "--interpreter-backend", "MIR", "--out-root", os.path.join(d, "m")], d)
    else:
        exe = os.path.join(d, "p.exe")
        calis([EXE, "bld", yol, "--build-x64", "--build-x64-out", exe, "--out-root", os.path.join(d, "x")], d)
        if os.path.exists(exe):
            shutil.copy(RT, d)
            rc, c = calis([exe], d)
        else:
            rc, c = -1, ["x64 derlenemedi"]
    print("=====", m, "rc=", rc)
    for s in c:
        print("  ", s)
sunucu.shutdown()
shutil.rmtree(d, ignore_errors=True)

