# -*- coding: utf-8 -*-
"""libsx/*/*.bas ve include/modules/*.uxmh dosyalarından kütüphane işlev envanteri çıkarır."""
import os, re, sys, json
sys.stdout.reconfigure(encoding="utf-8")
KOK = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
LIBSX = os.path.join(KOK, "libsx")
MOD = os.path.join(KOK, "include", "modules")
sonuc = {}
for ad in sorted(os.listdir(MOD)):
    if not ad.endswith(".uxmh"):
        continue
    lib = ad[:-5]
    govde = open(os.path.join(MOD, ad), encoding="utf-8", errors="replace").read()
    hedefler = re.findall(r'INCLUDE\s+"([^"]+)"', govde)
    kayit = {"hedef": hedefler, "ns": [], "islev": [], "dll": set(), "const": 0, "type": 0}
    for h in hedefler:
        p = os.path.join(KOK, h.replace("/", os.sep))
        if not os.path.exists(p):
            kayit["eksik_dosya"] = h
            continue
        for s in open(p, encoding="utf-8", errors="replace").read().splitlines():
            t = s.strip()
            m = re.match(r"(?i)^NAMESPACE\s+(\w+)", t)
            if m:
                kayit["ns"].append(m.group(1))
            m = re.match(r"(?i)^(FUNCTION|SUB)\s+(\w+)\s*\((.*?)\)(?:\s+AS\s+(\w+))?", t)
            if m:
                kayit["islev"].append(f"{m.group(1).upper()} {m.group(2)}({m.group(3)})" + (f" AS {m.group(4)}" if m.group(4) else ""))
            for d in re.findall(r'CALL\(DLL,\s*"([^"]+)"', t):
                kayit["dll"].add(d)
            if re.match(r"(?i)^CONST\b", t):
                kayit["const"] += 1
            if re.match(r"(?i)^TYPE\b", t):
                kayit["type"] += 1
    kayit["dll"] = sorted(kayit["dll"])
    sonuc[lib] = kayit
json.dump(sonuc, open(os.path.join(os.environ["TEMP"], "kv2", "lib_envanter.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
for lib, k in sonuc.items():
    print(f"{lib:<22} ns={','.join(k['ns']) or '-':<22} işlev={len(k['islev']):<4} dll={','.join(k['dll']) or '-':<28} {('EKSİK DOSYA ' + k['eksik_dosya']) if k.get('eksik_dosya') else ''} hedef={k['hedef']}")

# -*- coding: utf-8 -*-
"""libsx sarmalayıcılarının CALL(DLL, "x.dll", "sembol") çağrılarındaki sembollerin gerçekten DLL'de dışa aktarıldığını denetler."""
import ctypes, os, re, sys, json
sys.stdout.reconfigure(encoding="utf-8")
KOK = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
BIN = os.path.join(KOK, "bin")
os.add_dll_directory(BIN)
os.environ["PATH"] = BIN + os.pathsep + os.environ["PATH"]
sonuc = {}
for dp, dn, fn in os.walk(os.path.join(KOK, "libsx")):
    for f in fn:
        if not f.lower().endswith(".bas"):
            continue
        p = os.path.join(dp, f)
        for s in open(p, encoding="utf-8", errors="replace"):
            for dll, sym in re.findall(r'CALL\(DLL,\s*"([^"]+)"\s*,\s*"([^"]+)"', s):
                sonuc.setdefault(dll.lower(), {}).setdefault(sym, set()).add(os.path.relpath(p, KOK))
rapor = {}
for dll, semboller in sorted(sonuc.items()):
    yol = os.path.join(BIN, dll)
    if not os.path.exists(yol):
        rapor[dll] = {"yuklenemedi": "DLL bin klasöründe yok", "sembol_sayisi": len(semboller)}
        continue
    try:
        h = ctypes.WinDLL(yol)
    except OSError as e:
        rapor[dll] = {"yuklenemedi": str(e)[:120], "sembol_sayisi": len(semboller)}
        continue
    eksik = [s for s in semboller if not hasattr(h, s)]
    rapor[dll] = {"sembol_sayisi": len(semboller), "eksik": sorted(eksik)}
for dll, r in rapor.items():
    if "yuklenemedi" in r:
        print(f"{dll:<24} YÜKLENEMEDİ ({r['yuklenemedi']}) · sembol {r['sembol_sayisi']}")
    else:
        print(f"{dll:<24} sembol {r['sembol_sayisi']:<4} eksik {len(r['eksik'])}" + (f"  → {r['eksik'][:6]}" if r["eksik"] else ""))
json.dump(rapor, open(os.path.join(os.environ["TEMP"], "kv2", "dll_sembol_denetimi.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)

