import json, sys
sys.stdout.reconfigure(encoding="utf-8")
j = json.load(open(sys.argv[1], encoding="utf-8"))
def yurut(o, yol=""):
    if isinstance(o, dict):
        for k, v in o.items():
            yield from yurut(v, yol + "/" + str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o):
            yield from yurut(v, yol + "[" + str(i) + "]")
    else:
        yield yol, o
print("ust anahtarlar:", list(j.keys()) if isinstance(j, dict) else type(j))
n = 0
for yol, deger in yurut(j):
    if isinstance(deger, str) and "kullanilmis" in deger.lower():
        print(yol, "=", deger[:120])
        n += 1
        if n >= 40:
            break
'@; Set-Content "$sp\mir_ara.py" $py -Encoding UTF8; python "$sp\mir_ara.py" "$sp\mirdump\mir_full.json"

