Set-Location 'C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb'; $yol = 'docs\kitaplar\_ortak\ornekler\66_kv_ic_ice\kutuphane_dil_zinciri.uxb'; $enc = New-Object System.Text.UTF8Encoding($false); $t = [System.IO.File]::ReadAllText((Resolve-Path $yol), $enc); $once = $t.Length;
# 1) üç dizi bildirimini asıl yerinden çıkar
$kaldir = "    DIM kullanilmis(7) AS I32`r`n    DIM adlar(7) AS STRING`r`n    DIM toplam(7) AS I64`r`n"; if (-not $t.Contains($kaldir)) { $kaldir = $kaldir.Replace("`r`n", "`n") }
if (-not $t.Contains($kaldir)) { throw 'dizi bildirimleri bulunamadi' }
$t = $t.Replace($kaldir, '');
# 2) MAIN'in hemen altına, açıklamalı olarak koy
$satirSonu = if ($t.Contains("`r`n")) { "`r`n" } else { "`n" };
$ekle = "MAIN" + $satirSonu + "    ' Diziler yordamin basinda, ilk cagridan once bildirilir (x64'te ASSERT varken sonradan DIM yazmak derlenmez: G-DIL-10)" + $satirSonu + "    DIM kullanilmis(7) AS I32" + $satirSonu + "    DIM adlar(7) AS STRING" + $satirSonu + "    DIM toplam(7) AS I64" + $satirSonu;
$t = $t.Replace("MAIN" + $satirSonu, $ekle);
# 3) başlık: ZAMAN ve açıklama notu
$t = $t.Replace("' CALISMA:", "' CALISMA:");
$t = $t.Replace("(G-HIZ-2).", "(G-HIZ-2). Diziler MAIN'in basinda bildirilir; ASSERT bulunan bir programda dizi bildirimini bir cagridan sonraya koymak x64'te derlenmez (G-DIL-10, S-203).");
if (-not $t.Contains("' ZAMAN:")) { $t = $t.Replace("'= gecerli olay", "' ZAMAN: 300" + $satirSonu + "'= gecerli olay") }
[System.IO.File]::WriteAllText((Resolve-Path $yol), $t, $enc);
"uzunluk: $once -> " + $t.Length; (Get-Content $yol -TotalCount 7 | ForEach-Object { $_.Substring(0, [Math]::Min(110, $_.Length)) }); '...'; Get-Content $yol | Select-String -Pattern 'MAIN|DIM kullanilmis|DIM adlar|DIM toplam|ZAMAN' | ForEach-Object { $_.LineNumber.ToString() + ': ' + $_.Line.Trim().Substring(0, [Math]::Min(100, $_.Line.Trim().Length)) }

